Here is the commit message:
bridge: br_nd_send: linearize skb before parsing ND options

br_nd_send() parses neighbour discovery options from ns->opt[] and
assumes that these options are in the linear part of request.

Its callers only guarantee that the ICMPv6 header and target address
are available, so the option area can still be non-linear. Parsing
ns->opt[] in that case can access data past the linear buffer.

Linearize request before option parsing and derive ns from the linear
network header.

Fixes: ed842faeb2bd ("bridge: suppress nd pkts on BR_NEIGH_SUPPRESS ports")
Reported-by: Yifan Wu <yifanwucs@gmail.com>
Reported-by: Juefei Pu <tomapufckgml@gmail.com>
Tested-by: Ao Zhou <n05ec@lzu.edu.cn>
Co-developed-by: Yuan Tan <tanyuan98@outlook.com>
Signed-off-by: Yuan Tan <tanyuan98@outlook.com>
Suggested-by: Xin Liu <bird@lzu.edu.cn>
Signed-off-by: Yang Yang <n05ec@lzu.edu.cn>
Reviewed-by: Ido Schimmel <idosch@nvidia.com>
Acked-by: Nikolay Aleksandrov <razor@blackwall.org>
Link: https://patch.msgid.link/20260326034441.2037420-2-n05ec@lzu.edu.cn
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The function br_nd_send() in br_arp_nd_proxy.c parses neighbour discovery options from ns->opt[] assuming these options reside in the linear part of the skb. However, its callers only guarantee that the ICMPv6 header and target address are linear. When the skb is non-linear, accessing ns->opt[] can read data beyond the linear buffer, causing a crash or other memory safety issues.

Here is the patch:

 static void br_nd_send(struct net_bridge *br, struct net_bridge_port *p,
 		       struct sk_buff *request, struct neighbour *n,
-		       __be16 vlan_proto, u16 vlan_tci, struct nd_msg *ns)
+		       __be16 vlan_proto, u16 vlan_tci)
 {
 	struct net_device *dev = request->dev;
 	struct net_bridge_vlan_group *vg;
+	struct nd_msg *na, *ns;
 	struct sk_buff *reply;
-	struct nd_msg *na;
 	struct ipv6hdr *pip6;
 	int na_olen = 8; /* opt hdr + ETH_ALEN for target */
 	int ns_olen;
 	int i, len;
 	u8 *daddr;
 	u16 pvid;

-	if (!dev)
+	if (!dev || skb_linearize(request))
 		return;

 	len = LL_RESERVED_SPACE(dev) + sizeof(struct ipv6hdr) +
 		sizeof(*na) + na_olen + dev->needed_tailroom;

 	reply = alloc_skb(len, GFP_ATOMIC);
 	if (!reply)
 		return;

 	reply->protocol = htons(ETH_P_IPV6);
 	reply->dev = dev;
 	skb_reserve(reply, LL_RESERVED_SPACE(dev));
 	skb_push(reply, sizeof(struct ethhdr));
 	skb_set_mac_header(reply, 0);

 	daddr = eth_hdr(request)->h_source;
+	ns = (struct nd_msg *)(skb_network_header(request) +
+			       sizeof(struct ipv6hdr));

 	/* Do we need option processing ? */
 	ns_olen = request->len - (skb_network_offset(request) +
 				  sizeof(struct ipv6hdr)) - sizeof(*ns);
 	for (i = 0; i < ns_olen - 1; i += (ns->opt[i + 1] << 3)) {
 		if (!ns->opt[i + 1]) {
 			kfree_skb(reply);
 			return;
 		}
 		if (ns->opt[i] == ND_OPT_SOURCE_LL_ADDR) {
 			daddr = ns->opt + i + sizeof(struct nd_opt_hdr);
 			break;
 		}
 	}

 	/* Ethernet header */
 	ether_addr_copy(eth_hdr(reply)->h_dest, daddr);
 	ether_addr_copy(eth_hdr(reply)->h_source, n->ha);
 	eth_hdr(reply)->h_proto = htons(ETH_P_IPV6);
 	reply->protocol = htons(ETH_P_IPV6);

 	skb_pull(reply, sizeof(struct ethhdr));
 	skb_set_network_header(reply, 0);
 	skb_put(reply, sizeof(struct ipv6hdr));

 	/* IPv6 header */
 	pip6 = ipv6_hdr(reply);
 	memset(pip6, 0, sizeof(struct ipv6hdr));
 	pip6->version = 6;
 	pip6->priority = ipv6_hdr(request)->priority;
 	pip6->nexthdr = IPPROTO_ICMPV6;
 	pip6->hop_limit = 255;
 	pip6->daddr = ipv6_hdr(request)->saddr;
 	pip6->saddr = *(struct in6_addr *)n->primary_key;

 	skb_pull(reply, sizeof(struct ipv6hdr));
 	skb_set_transport_header(reply, 0);

 	na = (struct nd_msg *)skb_put(reply, sizeof(*na) + na_olen);

 	/* Neighbor Advertisement */
 	memset(na, 0, sizeof(*na) + na_olen);
 	na->icmph.icmp6_type = NDISC_NEIGHBOUR_ADVERTISEMENT;
 	na->icmph.icmp6_router = (n->flags & NTF_ROUTER) ? 1 : 0;
 	na->icmph.icmp6_override = 1;
 	na->icmph.icmp6_solicited = 1;
 	na->target = ns->target;
 	ether_addr_copy(&na->opt[2], n->ha);
 	na->opt[0] = ND_OPT_TARGET_LL_ADDR;
 	na->opt[1] = na_olen >> 3;

 	na->icmph.icmp6_cksum = csum_ipv6_magic(&pip6->saddr,
 						&pip6->daddr,
 						sizeof(*na) + na_olen,
 						IPPROTO_ICMPV6,
 						csum_partial(na, sizeof(*na) + na_olen, 0));

 	pip6->payload_len = htons(sizeof(*na) + na_olen);

 	skb_push(reply, sizeof(struct ipv6hdr));
 	skb_push(reply, sizeof(struct ethhdr));

 	reply->ip_summed = CHECKSUM_UNNECESSARY;

 	if (p)
 		vg = nbp_vlan_group_rcu(p);
 	else
 		vg = br_vlan_group_rcu(br);
 	pvid = br_get_pvid(vg);
 	if (pvid == (vlan_tci & VLAN_VID_MASK))
 		vlan_tci = 0;

 	if (vlan_tci)
 		__vlan_hwaccel_put_tag(reply, vlan_proto, vlan_tci);

 	netdev_dbg(dev, "nd send dev %s dst %pI6 dst_hw %pM src %pI6 src_hw %pM\n",
 		   dev->name, &pip6->daddr, daddr, &pip6->saddr, n->ha);

 	if (p) {
 		dev_queue_xmit(reply);
 	} else {
 		skb_reset_mac_header(reply);
 		__skb_pull(reply, skb_network_offset(reply));
 		reply->ip_summed = CHECKSUM_UNNECESSARY;
 		reply->pkt_type = PACKET_HOST;

 		netif_rx(reply);
 	}
 }


 void br_do_suppress_nd(struct sk_buff *skb, struct net_bridge *br,
 		       u16 vid, struct net_bridge_port *p, struct nd_msg *msg)
 {
 	struct net_device *dev = br->dev;
 	struct net_device *vlandev = NULL;
 	struct in6_addr *saddr, *daddr;
 	struct ipv6hdr *iphdr;
 	struct neighbour *n;

 	BR_INPUT_SKB_CB(skb)->proxyarp_replied = 0;

 	if (br_is_neigh_suppress_enabled(p, vid))
 		return;

 	if (is_unicast_ether_addr(eth_hdr(skb)->h_dest) &&
 	    msg->icmph.icmp6_type == NDISC_NEIGHBOUR_SOLICITATION)
 		return;

 	if (msg->icmph.icmp6_type == NDISC_NEIGHBOUR_ADVERTISEMENT &&
 	    !msg->icmph.icmp6_solicited) {
 		/* prevent flooding to neigh suppress ports */
 		BR_INPUT_SKB_CB(skb)->proxyarp_replied = 1;
 		return;
 	}

 	if (msg->icmph.icmp6_type != NDISC_NEIGHBOUR_SOLICITATION)
 		return;

 	iphdr = ipv6_hdr(skb);
 	saddr = &iphdr->saddr;
 	daddr = &iphdr->daddr;

 	if (ipv6_addr_any(saddr) || !ipv6_addr_cmp(saddr, daddr)) {
 		/* prevent flooding to neigh suppress ports */
 		BR_INPUT_SKB_CB(skb)->proxyarp_replied = 1;
 		return;
 	}

 	if (vid != 0) {
 		/* build neigh table lookup on the vlan device */
 		vlandev = __vlan_find_dev_deep_rcu(br->dev, skb->vlan_proto,
 						   vid);
 		if (!vlandev)
 			return;
 	} else {
 		vlandev = dev;
 	}

 	if (br_is_local_ip6(vlandev, &msg->target)) {
 		/* its our own ip, so don't proxy reply
 		 * and don't forward to arp suppress ports
 		 */
 		BR_INPUT_SKB_CB(skb)->proxyarp_replied = 1;
 		return;
 	}

 	n = neigh_lookup(ipv6_stub->nd_tbl, &msg->target, vlandev);
 	if (n) {
 		struct net_bridge_fdb_entry *f;

 		if (!(READ_ONCE(n->nud_state) & NUD_VALID)) {
 			neigh_release(n);
 			return;
 		}

 		f = br_fdb_find_rcu(br, n->ha, vid);
 		if (f) {
 			bool replied = false;

 			if (br_is_neigh_suppress_enabled(f->dst, vid)) {
 				if (vid != 0)
 					br_nd_send(br, p, skb, n,
 						   skb->vlan_proto,
-						   skb_vlan_tag_get(skb), msg);
+						   skb_vlan_tag_get(skb));
 				else
-					br_nd_send(br, p, skb, n, 0, 0, msg);
+					br_nd_send(br, p, skb, n, 0, 0);
 				replied = true;
 			}

 			/* If we have replied or as long as we know the
 			 * mac, indicate to NEIGH_SUPPRESS ports that we
 			 * have replied
 			 */
 			if (replied ||
 			    br_opt_get(br, BROPT_NEIGH_SUPPRESS_ENABLED))
 				BR_INPUT_SKB_CB(skb)->proxyarp_replied = 1;
 		}
 		neigh_release(n);
 	}
 }
 #endif


